# ===== SECTION 1: helper functions =====

def count_words(sentence):
    return len(sentence.split())


def longest_word(sentence):
    longest = ""
    for word in sentence.split():
        if len(word) > len(longest):
            longest = word
    return longest


# ===== SECTION 2: main program =====

def main():
    sentences = ["Python is fun", "Functions keep code tidy", "Scope matters"]
    total = 0
    for sentence in sentences:
        n = count_words(sentence)
        total = total + n
        print(sentence + ": " + str(n) + " words, longest: " + longest_word(sentence))
    print("Total words: " + str(total))


if __name__ == "__main__":
    main()
